    public static string Get(string en, GameLanguage language)
    {
        if (string.IsNullOrEmpty(en)) return en;
        if (!Map.TryGetValue(en, out Entry e)) return en;
        switch (language)
        {
            case GameLanguage.Thai: return e.Th;
            case GameLanguage.Spanish: return e.Es;
            case GameLanguage.Portuguese: return e.Pt;
            case GameLanguage.French: return e.Fr;
            case GameLanguage.Italian: return e.It;
            case GameLanguage.German: return e.De;
            default: return en;
        }
    }

    public static bool MatchesEnglishKey(string enKey, string candidate)
    {
        if (string.IsNullOrEmpty(candidate)) return false;
        if (candidate == enKey) return true;
        if (!Map.TryGetValue(enKey, out Entry e)) return false;
        return candidate == e.Th || candidate == e.Es || candidate == e.Pt
            || candidate == e.Fr || candidate == e.It || candidate == e.De;
    }
}
